        # orientation: endpoints at the bounding-box corners occupied.
        minr=min(y for y,x in comp); maxr=max(y for y,x in comp)
        minc=min(x for y,x in comp); maxc=max(x for y,x in comp)
        candidates=[(minr,minc),(minr,maxc),(maxr,minc),(maxr,maxc)]
